from __future__ import annotations

"""Record listening history and roll it up for stats and recommendations.

Every play becomes a ``PlayEvent``. History, play counts, and "top tracks" all
key off the track id on that event, so the id has to be the one identity a song
keeps no matter which market it streamed in.
"""

from dataclasses import dataclass

from relinked_track import Track


@dataclass(frozen=True)
class PlayEvent:
    track_id: str
    track_name: str
    played_at: str
    user_id: str


def log_play(track: Track, played_at: str, user_id: str) -> PlayEvent:
    """Turn one playback into a history event."""

    return PlayEvent(
        track_id=track.id,
        track_name=track.name,
        played_at=played_at,
        user_id=user_id,
    )


def log_plays(plays: list[tuple[Track, str, str]]) -> list[PlayEvent]:
    """Log a batch of (track, played_at, user_id) tuples."""

    return [log_play(track, played_at, user_id) for track, played_at, user_id in plays]


def play_counts(events: list[PlayEvent]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for event in events:
        counts[event.track_id] = counts.get(event.track_id, 0) + 1
    return counts


def top_track_id(events: list[PlayEvent]) -> str | None:
    counts = play_counts(events)
    if not counts:
        return None
    return max(counts, key=lambda track_id: (counts[track_id], track_id))


def build_recently_played(events: list[PlayEvent]) -> list[str]:
    """Most-recent-first track ids, collapsing immediate repeats of one song."""

    recent: list[str] = []
    for event in reversed(events):
        if recent and recent[-1] == event.track_id:
            continue
        recent.append(event.track_id)
    return recent


def summarize_history(events: list[PlayEvent]) -> dict[str, object]:
    counts = play_counts(events)
    return {
        "event_count": len(events),
        "distinct_tracks": len(counts),
        "top_track_id": top_track_id(events),
        "counts": counts,
    }

