from __future__ import annotations

"""Track objects that may have been relinked for the user's market.

When a requested track is not playable in the user's market, Spotify returns a
different, playable track in its place and records the originally requested track
under ``linked_from``::

    {
        "id": "4PLAYABLE_DE",
        "name": "Song",
        "uri": "spotify:track:4PLAYABLE_DE",
        "is_playable": true,
        "linked_from": {"id": "1ORIGINAL", "uri": "spotify:track:1ORIGINAL"}
    }

The ``id`` here is the market substitute that actually streams; ``linked_from``
is the stable identity the catalog and a user's history share across markets.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class LinkedFrom:
    id: str
    uri: str

    def __post_init__(self) -> None:
        if not self.id.strip():
            raise ValueError("linked_from id is required")


@dataclass(frozen=True)
class Track:
    id: str
    name: str
    uri: str
    is_playable: bool = True
    linked_from: LinkedFrom | None = None

    def __post_init__(self) -> None:
        if not self.id.strip():
            raise ValueError("track id is required")
        if not self.name.strip():
            raise ValueError("track name is required")

    def is_relinked(self) -> bool:
        return self.linked_from is not None

    @classmethod
    def from_raw(cls, raw: dict) -> "Track":
        linked_raw = raw.get("linked_from")
        linked = None
        if linked_raw:
            linked = LinkedFrom(
                id=str(linked_raw.get("id", "")),
                uri=str(linked_raw.get("uri", "")),
            )
        return cls(
            id=str(raw.get("id", "")),
            name=str(raw.get("name", "")),
            uri=str(raw.get("uri", "")),
            is_playable=bool(raw.get("is_playable", True)),
            linked_from=linked,
        )


def build_track(track_id: str, name: str, linked_from_id: str | None = None) -> Track:
    linked = None
    if linked_from_id is not None:
        linked = LinkedFrom(id=linked_from_id, uri=f"spotify:track:{linked_from_id}")
    return Track(
        id=track_id,
        name=name,
        uri=f"spotify:track:{track_id}",
        is_playable=True,
        linked_from=linked,
    )

